286 // findModuleRoot goes up from dir to the first directory that holds a go.mod.
287 // Inside a worktree that is the worktree's own go.mod, not the main checkout's.
288 func findModuleRoot(dir string) (string, error) {
289     dir, err := filepath.Abs(dir)
290     if err != nil {
291         return "", err
292     }
293     for {
294         if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
295             return dir, nil
296         }
297         parent := filepath.Dir(dir)
298         if parent == dir {
299             return "", fmt.Errorf("no go.mod above %s", dir)
300         }
301         dir = parent
302     }
303 }
304 
305 // scanTree scans every non-test .go file under root. The excluded directories
306 // are matched on the names of the entries below root, never on root's own
307 // absolute path: a checkout that lives under .worktrees is still scanned.
308 // It also returns the number of files read.
309 func scanTree(root string) ([]violation, int, error) {
310     var all []violation
311     files := 0
312     err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
313         if err != nil {
314             return err
315         }
316         rel, err := filepath.Rel(root, p)
317         if err != nil {
318             return err
319         }
320         rel = filepath.ToSlash(rel)
321         if d.IsDir() {
322             if rel != "." && (slices.Contains(guardExcludedDirs, d.Name()) || rel == guardOwnDir) {
323                 return filepath.SkipDir
324             }
325             return nil
326         }
327         if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
328             return nil
329         }
330         src, err := os.ReadFile(p)
331         if err != nil {
332             return err
333         }
334         vs, err := scanSource(rel, src)
335         if err != nil {
336             return err
337         }
338         files++
339         all = append(all, vs...)
340         return nil
341     })
342     return all, files, err
343 }
344 
345 var (
346     repoOnce       sync.Once
347     repoRoot       string
348     repoViolations []violation
349     repoFiles      int
350     repoErr        error
351 )
352 
353 // scanRepo scans the module that holds this package, once per test process.
354 func scanRepo(t *testing.T) (string, []violation) {
355     t.Helper()
356     repoOnce.Do(func() {
357         wd, err := os.Getwd()
358         if err != nil {
359             repoErr = err
360             return
361         }
362         if repoRoot, repoErr = findModuleRoot(wd); repoErr != nil {
363             return
364         }
365         repoViolations, repoFiles, repoErr = scanTree(repoRoot)
366     })
367     if repoErr != nil {
368         t.Fatalf("scanning the module: %v", repoErr)
369     }
370     // A walk that reads almost nothing would pass for the wrong reason.
371     if repoFiles < 50 {
372         t.Fatalf("the guard read %d files under %s, want the whole module", repoFiles, repoRoot)
373     }
374     return repoRoot, repoViolations
375 }
